"use strict";
const P=require("./paths");
const timeline=c=>["append-footage","sequence-review","sequence-error"].includes(c.kind);
const media=c=>["new-file","fragmented"].includes(c.kind);
const needs=c=>Boolean(c.blocking)&&c.kind!=="unavailable";
// IDs are regenerated by the planner. Decisions are bound to the source version,
// never to its row number, and survive unrelated additions/removals.
const changeKey=c=>JSON.stringify([c.kind,P.key(c.path||""),c.from,c.itemId,c.file?.size,c.file?.mtime,c.file?.identity,c.source?.path,c.source?.signature,c.source?.revision,c.entry?.key,c.entry?.attempt,c.entry?.failure,c.expected]);
function countChanges(changes=[],universe=changes) { const imports=new Set(universe.filter(media).map(c=>P.key(c.path)));return changes.filter(c=>c.kind!=="unavailable"&&(!timeline(c)||c.kind!=="sequence-error"&&!imports.has(P.key(c.path)))).length; }
function summary(batch={}) {const changes=batch.changes||[];return {count:countChanges(changes),needs:changes.filter(needs).length,unavailable:changes.filter(c=>c.kind==="unavailable").length};}
function category(c) {return timeline(c)?"Add new videos to timeline":media(c)?"New files":c.kind==="new-folder"?"New bins":["clip-markers","marker-choice"].includes(c.kind)?"Clip markers":"Renamed and moved";}
function groups(changes,by="Type",batch={}) {
  const result=new Map();
  for(const c of changes){let folder=P.dirname(c.file?.path||c.path)||"Project root";if(["new-folder","folder-move"].includes(c.kind)){const link=batch.links?.find(l=>l.id===c.linkId),dir=batch.next?.[c.linkId]?.dirs?.find(d=>d.binPath===c.path);folder=dir?.path||(link&&c.path!==link.binPath&&P.within(c.path,link.binPath)?P.join(P.resolve(P.dirname(batch.projectPath),link.folderPath),P.relative(link.binPath,c.path)):c.path);}const name=by==="Folder"&&!timeline(c)?folder:category(c);if(!result.has(name))result.set(name,[]);result.get(name).push(c);}
  const order=["New files","New bins","Renamed and moved","Add new videos to timeline","Clip markers"];
  return [...result].sort((a,b)=>by==="Type"?order.indexOf(a[0])-order.indexOf(b[0]):Number(a[0]==="Add new videos to timeline")-Number(b[0]==="Add new videos to timeline")||a[0].localeCompare(b[0])).map(([name,items])=>({name,items}));
}
class ChangesState {
  constructor(){this.decisions=new Map();this.unchecked=new Set();this.expanded=new Set();this.groupBy="Type";this.scroll=0;this.indices=new WeakMap();}
  sources(batch){
    const changes=batch.changes, cached=this.indices.get(batch);
    if(cached && cached.changes===changes && cached.length===changes.length)return cached;
    const paths=new Map(), folders=new Map();
    for(const c of changes){
      if(media(c))paths.set(P.key(c.path),c);
      if(c.kind==="new-folder"){
        const path=P.key(c.path);
        if(!folders.has(path))folders.set(path,[]);
        folders.get(path).push(c);
      }
    }
    const indices={changes,length:changes.length,paths,folders};
    this.indices.set(batch,indices);
    return indices;
  }
  decide(c,value){this.decisions.set(changeKey(c),value);this.unchecked.delete(changeKey(c));}
  decision(c){return this.decisions.get(changeKey(c));}
  clearDeferred(){for(const [key,value] of this.decisions)if(value==="defer")this.decisions.delete(key);}
  check(c,value){if(value)this.unchecked.delete(changeKey(c));else this.unchecked.add(changeKey(c));}
  selected(c,batch){
    if(c.kind==="unavailable"||this.unchecked.has(changeKey(c)))return false;
    // Each required bin is already on this path. Recursing through every
    // ancestor revisits the same prefixes exponentially in a deep preview.
    const folders=this.sources(batch).folders;
    let target=P.key(c.kind==="new-folder"?P.dirname(c.path):c.target);
    while(target && folders.size){
      if(folders.get(target)?.some(bin=>bin!==c && (needs(bin)||this.unchecked.has(changeKey(bin)))))return false;
      const parent=P.dirname(target);
      if(parent===target)break;
      target=parent;
    }
    const value=this.decision(c);
    if(needs(c)&&!(c.kind==="fragmented"&&value==="original")&&!(c.kind==="marker-choice"&&["replace","append","skip"].includes(value))&&!(c.kind==="sequence-review"&&["retry","keep"].includes(value)))return false;
    if((timeline(c)||["clip-markers","marker-choice"].includes(c.kind))&&!c.checkpoint&&value!=="keep"){
      const source=this.sources(batch).paths.get(P.key(c.path));if(source&&!this.selected(source,batch))return false;
    }
    return true;
  }
  selection(batch){
    const selected=batch.changes.filter(c=>this.selected(c,batch)),decisions={};
    for(const c of selected)if(this.decision(c))decisions[c.id]=this.decision(c);
    const selectedMedia=new Set(selected.filter(media).map(c=>P.key(c.path))),sources=this.sources(batch).paths;
    const skipSequenceKeys=batch.changes.filter(c=>timeline(c)&&c.entry&&this.unchecked.has(changeKey(c))&&(!sources.has(P.key(c.path))||selectedMedia.has(P.key(c.path)))).map(c=>c.entry.key);
    return {selected:selected.map(c=>c.id),decisions,options:{skipSequenceKeys},count:countChanges(selected),waiting:batch.changes.filter(c=>needs(c)&&!this.decision(c)).length};
  }
}
module.exports={ChangesState,changeKey,countChanges,summary,category,groups,timeline,media,needs};
